  cargarAyuda();
  cargarFuentes();
  cargarCola();
  // Estilo Job Runner: la tabla se refresca sola mientras la ingesta avanza,
  // sin que el usuario tenga que recargar la página a mano.
  setInterval(() => {
    cargarCola();
